let s;try{const stored=JSON.parse(localStorage.getItem(KEY)||"null");s={...fresh(),...(stored||{})};const f=fresh();for(const k of Object.keys(f))if(s[k]===undefined)s[k]=f[k];s.inventory=s.inventory&&typeof s.inventory==="object"&&!Array.isArray(s.inventory)?s.inventory:{};s.daily=s.daily&&typeof s.daily==="object"?s.daily:{...f.daily};s.daily.minutes=Number(s.daily.minutes)||0;s.daily.cards=Number(s.daily.cards)||0;s.daily.trainers=Number(s.daily.trainers)||0;s.daily.claimed=Array.isArray(s.daily.claimed)?s.daily.claimed:[];s.weekly=s.weekly&&typeof s.weekly==="object"?s.weekly:{...f.weekly};s.weekly.cards=Number(s.weekly.cards)||0;s.weekly.minutes=Number(s.weekly.minutes)||0;s.weekly.claimed=Array.isArray(s.weekly.claimed)?s.weekly.claimed:[];s.processedSessions=Array.isArray(s.processedSessions)?s.processedSessions:[];s.buildings=Array.isArray(s.buildings)?s.buildings:f.buildings.map(b=>({...b}));s.buildings=s.buildings.filter(b=>b&&defs[b.type]&&Number.isFinite(Number(b.x))&&Number.isFinite(Number(b.y))).map(b=>({...b,x:Math.floor(Number(b.x)),y:Math.floor(Number(b.y)),l:Math.max(1,Number(b.l)||1)}));s.tech=Array.isArray(s.tech)?s.tech:[];s.regions=Array.isArray(s.regions)?s.regions:[];s.capacity=Math.max(500,Number(s.capacity)||500);for(const k of ["coins","xp","level","knowledge","wood","stone","wheat","flour","bread","planks","ore","iron","pop","mood","food","units","archers","cavalry","allTimeMinutes"])s[k]=Number.isFinite(Number(s[k]))?Number(s[k]):Number(f[k]||0);s.level=Math.max(1,s.level);s.regions=s.regions.filter(x=>typeof x==="string");if(stored&&!stored.welcomePackage){s.coins+=650;s.wood+=90;s.stone+=60;s.wheat+=80;s.units+=5;s.welcomePackage=true}s.regions=Array.isArray(s.regions)?s.regions:[];s.populationTicks=s.populationTicks||0;s.cityPolicy=["balanced","welfare","growth","education","security"].includes(s.cityPolicy)?s.cityPolicy:"balanced";s.eventLog=Array.isArray(s.eventLog)?s.eventLog.slice(-12):["Aurelion wurde gegründet."];s.lastCityEvent=Number(s.lastCityEvent)||Date.now();s.season=s.season||"Frühling";s.garrisons=s.garrisons&&typeof s.garrisons==="object"?s.garrisons:{};s.treaties=Array.isArray(s.treaties)?s.treaties:[];s.armyPosition=s.armyPosition&&Number.isFinite(Number(s.armyPosition.x))&&Number.isFinite(Number(s.armyPosition.y))?{x:Math.max(0,Math.floor(Number(s.armyPosition.x))),y:Math.max(0,Math.floor(Number(s.armyPosition.y)))}:{x:11,y:8};s.campaigns=Array.isArray(s.campaigns)?s.campaigns:[];s.regionData=s.regionData&&typeof s.regionData==="object"?s.regionData:{};s.tradeRoutes=Array.isArray(s.tradeRoutes)?s.tradeRoutes:[];s.governors=s.governors&&typeof s.governors==="object"?s.governors:{};s.achievements=s.achievements&&typeof s.achievements==="object"?s.achievements:{};s.cityData=s.cityData&&typeof s.cityData==="object"?s.cityData:{};s.lastWorldEvent=Number(s.lastWorldEvent)||Date.now();s.worldEventCount=Math.max(0,Number(s.worldEventCount)||0);s.completedContracts=Array.isArray(s.completedContracts)?s.completedContracts:[];s.marketDay=typeof s.marketDay==="string"?s.marketDay:"";s.worldArmyPosition=["capital","river","iron","coast","north"].includes(s.worldArmyPosition)?s.worldArmyPosition:"capital";s.aiRealms=s.aiRealms&&typeof s.aiRealms==="object"?s.aiRealms:{};s.aiLastDay=typeof s.aiLastDay==="string"?s.aiLastDay:"";s.discoveredRegions=Array.isArray(s.discoveredRegions)?s.discoveredRegions.filter(x=>["river","iron","coast","north"].includes(x)):["river"];s.aiEvents=Array.isArray(s.aiEvents)?s.aiEvents.slice(-12):[];for(const region of (s.regions||[]))if(!s.discoveredRegions.includes(region))s.discoveredRegions.push(region);if(s.province&&!s.discoveredRegions.includes("river"))s.discoveredRegions.push("river");for(const key of ["river","iron","coast","north"]){const old=s.regionData[key]&&typeof s.regionData[key]==="object"?s.regionData[key]:{};s.regionData[key]={policy:["balanced","food","industry","research","trade"].includes(old.policy)?old.policy:"balanced",level:Math.max(1,Number(old.level)||1),prosperity:Math.max(0,Math.min(100,Number(old.prosperity)||50)),...old};}}catch{s=fresh()}
let tab="overview",selected=null,placing=null,armyMode=false,zoom=100,msg="",lastDaily=DAY();
const count=id=>s.buildings.filter(b=>b.type===id).length,owned=id=>s.tech.includes(id),levelFor=xp=>Math.floor(Math.sqrt(Math.max(0,xp)/250))+1,xpNext=()=>s.level*s.level*250;
const caps=()=>s.capacity+count("granary")*450;
function save(){localStorage.setItem(KEY,JSON.stringify(s))}
function note(t){msg=t;render()}
function addXP(n){s.xp+=n;const before=s.level;s.level=levelFor(s.xp);if(s.level>before){s.coins+=s.level*75;msg="🎉 Reichsstufe "+s.level+" erreicht! +"+s.level*75+" Bonus-Coins.";}}
function pay(c){return s.coins>=c[0]&&s.wood>=c[1]&&s.stone>=c[2]}
function spend(c){s.coins-=c[0];s.wood-=c[1];s.stone-=c[2]}
function add(k,n){s[k]=Math.min(caps(),Math.max(0,(s[k]||0)+n))}
function resetQuests(){const week=new Date();const monday=new Date(week);monday.setDate(week.getDate()-((week.getDay()+6)%7));const wk=monday.toLocaleDateString("en-CA");if(s.daily.date!==DAY())s.daily={date:DAY(),cards:0,trainers:0,minutes:0,claimed:[]};if(s.weekly.week!==wk)s.weekly={week:wk,cards:0,minutes:0,claimed:[]}}
function syncTimer(){let data={};try{data=JSON.parse(localStorage.getItem("studyspaceExtensionData")||"{}")}catch{}const sessions=data&&Array.isArray(data.studySessions)?data.studySessions:[];let minsTotal=0;for(const session of sessions){if(!session||typeof session!=="object"||!session.id||s.processedSessions.includes(session.id))continue;const mins=Math.floor((Number(session.seconds)||0)/60);s.processedSessions.push(session.id);if(mins<1)continue;const earned=mins*50;s.coins+=earned;addXP(mins*5);s.knowledge+=mins;s.allTimeMinutes+=mins;if(session.date===DAY())s.daily.minutes+=mins;if(session.date&&session.date>=s.weekly.week)s.weekly.minutes+=mins;minsTotal+=mins}if(s.processedSessions.length>2000)s.processedSessions=s.processedSessions.slice(-1200);if(minsTotal){msg="⏱️ "+minsTotal+" Lernminute(n): +"+minsTotal*50+" Coins, +"+minsTotal*5+" XP und +"+minsTotal+" Wissen.";save()}}
function cardEvent(){resetQuests();s.daily.cards++;s.weekly.cards++;save();render()}
function trainerEvent(){resetQuests();s.daily.trainers++;save();render()}
function terrain(x,y){const n=(x*11+y*5)%97;if(n<7)return"🌲";if(n<11)return"🌳";if(n<15)return"⛰️";if(n<19)return"🌊";if(n<25)return"🌾";if(n<29)return"🪨";return""}
function mapView(){
 const buildings=Array.isArray(s.buildings)?s.buildings:[];
 const regions=Array.isArray(s.regions)?s.regions:[];
 const width=Math.max(24,Math.min(80,24+regions.length*4));
 const height=Math.max(16,Math.min(44,16+regions.length*2));
 const getBuilding=(x,y)=>buildings.find(q=>q&&Number(q.x)===x&&Number(q.y)===y);
 let tiles="";
 for(let y=0;y<height;y++)for(let x=0;x<width;x++){
  const b=getBuilding(x,y),d=b&&defs[b.type]?defs[b.type]:null,isArmy=Number(s.armyPosition.x)===x&&Number(s.armyPosition.y)===y;
  let ground="";try{ground=terrain(x,y)||""}catch(_){}
  tiles+='<button type="button" class="empire-tile '+(d?"built building-"+b.type+" ":"")+(d&&selected===b.id?"selected ":"")+(isArmy?"army-here ":"")+'" data-cell="'+x+','+y+'" aria-label="'+(isArmy?"Armee bei ":"")+ (d?esc(defs[b.type][1]):"Freies Feld")+' '+x+','+y+'">'+(d?'<strong>'+d[0]+'</strong><small>'+esc(d[1])+'</small><i>St. '+Math.max(1,Number(b.l)||1)+'</i>':ground)+(isArmy?'<span class="empire-army-marker" title="Deine Armee">⚔️</span>':"")+'</button>';
 }
 const chosen=buildings.find(q=>q&&q.id===selected&&defs[q.type]);
 let info='<h3>Deine Hauptstadt</h3><p>Tippe auf ein Gebäude, um es auszuwählen. Wähle im Baumenü ein Gebäude und tippe anschließend auf ein freies Feld.</p>';
 if(chosen){const d=defs[chosen.type],lv=Math.max(1,Number(chosen.l)||1);info='<div class="empire-detail-icon">'+d[0]+'</div><span class="empire-kicker">GEBÄUDE · STUFE '+lv+'</span><h3>'+esc(d[1])+'</h3><p>'+esc(d[5])+'</p><p>Produktion: '+esc(prodText(chosen.type))+'</p><p>Arbeitskräfte: '+workers(chosen.type)+'</p><button class="empire-btn" data-action="upgrade" data-id="'+esc(chosen.id)+'">Upgrade versuchen</button>'}
 else if(placing&&defs[placing]){const d=defs[placing];info='<h3>'+d[0]+' '+esc(d[1])+'</h3><p>Wähle ein freies Feld auf der Karte.</p><button class="empire-btn secondary" data-action="cancel">Abbrechen</button>'}
 else if(armyMode)info='<div class="empire-detail-icon">⚔️</div><h3>Armee bewegen</h3><p>Wähle ein freies Feld in maximal drei Schritten Entfernung. Gebäude blockieren den Weg nicht, können aber nicht als Ziel dienen.</p><button class="empire-btn secondary" data-action="army-cancel">Bewegung abbrechen</button>';
 else info='<div class="empire-detail-icon">⚔️</div><h3>Armee bereit</h3><p>Deine Armee steht bei Feld '+s.armyPosition.x+', '+s.armyPosition.y+'. Du kannst sie über die Karte bewegen.</p><button class="empire-btn" data-action="army-mode">Armee bewegen</button>';
 const level=Math.max(1,Number(s.level)||1),xp=Math.max(0,Number(s.xp)||0),next=level*level*250;
 const progress=Math.max(0,Math.min(100,(xp-(level-1)*(level-1)*250)/Math.max(1,next-(level-1)*(level-1)*250)*100));
 const houseCount=buildings.filter(q=>q&&q.type==="house").length,pop=Math.max(0,Number(s.pop)||0),units=Math.max(0,Number(s.units)||0)+Math.max(0,Number(s.archers)||0)+Math.max(0,Number(s.cavalry)||0);
 const canProvince=level>=4&&buildings.some(q=>q&&q.type==="shipyard")&&Number(s.coins)>=1200&&Number(s.wood)>=180&&Number(s.stone)>=120&&!s.province;
 return '<div class="empire-heading"><div><span class="empire-kicker">HAUPTSTADT · KRONPROVINZ</span><h2>Aurelion</h2><p>'+buildings.length+' Gebäude · '+pop+'/'+(10+houseCount*8)+' Einwohner · '+units+' Truppen · Zufriedenheit '+Math.round(Number(s.mood)||0)+'%</p></div><div class="empire-zoom"><label>Zoom</label><input id="empireZoom" type="range" min="60" max="150" step="5" value="'+zoom+'"><b>'+zoom+'%</b></div></div><div class="empire-map-layout"><div class="empire-map-viewport"><div class="empire-map-title">✦ KRONPROVINZ <small>'+width+' × '+height+' Felder · '+buildings.length+' Bauwerke</small></div><div class="empire-grid" style="--zoom-factor:'+zoom/100+';grid-template-columns:repeat('+width+',48px)">'+tiles+'</div></div><aside class="empire-info">'+info+'<div class="empire-learning"><b>📚 Lernen baut dein Reich auf</b><p>1 gespeicherte Minute = 50 Coins + 5 XP + 1 Wissen.</p><div class="empire-bar"><i style="width:'+progress+'%"></i></div><small>'+xp+' XP · '+Math.max(0,next-xp)+' XP bis Stufe '+(level+1)+'</small></div></aside></div><div class="empire-expansion"><div><b>🗺️ Flussmark '+(s.province?"· Erschlossen":"· Neue Provinz")+'</b><p>Voraussetzung: Reichsstufe 4, Werft, 1.200 Coins, 180 Holz und 120 Stein.</p></div><button class="empire-btn" data-action="province" '+(!canProvince?"disabled":"")+'>'+(s.province?"✓ Erschlossen":"Provinz erschließen")+'</button></div>';
}
function totalUnits(){return s.units+s.archers+s.cavalry}
function populationCap(){return 10+count("house")*8+count("monument")*20+count("farmstead")*4}
function buildingDetail(b){const d=defs[b.type],l=b.l||1,c=[Math.floor(110*l*(owned("engineering")?.85:1)),Math.floor(28*l),Math.floor(22*l)];return '<div class="empire-detail-icon">'+d[0]+'</div><span class="empire-kicker">GEBÄUDE · STUFE '+l+'</span><h3>'+d[1]+'</h3><p>'+d[5]+'</p><p><b>Produktion:</b> '+prodText(b.type)+'</p><p><b>Arbeitskräfte:</b> '+workers(b.type)+'</p><button class="empire-btn" data-action="upgrade" data-id="'+b.id+'" '+(!pay(c)?"disabled":"")+' >Upgrade · '+c[0]+' Coins, '+c[1]+' Holz, '+c[2]+' Stein</button>'}
function prodText(t){return ({field:"Weizen alle 5 Minuten",lumber:"Holz alle 5 Minuten",quarry:"Stein alle 5 Minuten",mill:"Mehl aus 10 Weizen",bakery:"Brot aus 5 Mehl",sawmill:"Bauholz aus 8 Holz",ironmine:"Erz alle 5 Minuten",smelter:"Eisen aus 5 Erz",library:"Wissen alle 5 Minuten"})[t]||"Versorgung, Handel oder Verteidigung"}
function workers(t){return ({field:2,lumber:2,quarry:3,mill:2,bakery:2,sawmill:2,ironmine:3,smelter:3,library:2,barracks:2})[t]||1}
function buildView(){return '<div class="empire-heading"><div><span class="empire-kicker">BAUMEISTER & WIRTSCHAFT</span><h2>Gebäude errichten</h2><p>Wähle Produktionsketten passend zu deinen Vorräten. Neue Gebäude benötigen Coins und Baumaterial.</p></div></div><div class="empire-cards">'+Object.entries(defs).filter(([k])=>k!=="hall").map(([k,d])=>'<article class="empire-card"><div>'+d[0]+'</div><h3>'+d[1]+'</h3><p>'+d[5]+'</p><small>🪙 '+d[2]+' · 🪵 '+d[3]+' · 🪨 '+d[4]+(d[6]?" · Stufe "+d[6]:"")+'</small><button class="empire-btn" data-action="choose" data-type="'+k+'" '+(!pay([d[2],d[3],d[4]])||s.level<(d[6]||1)?"disabled":"")+'>'+(s.level<(d[6]||1)?"Ab Stufe "+d[6]:pay([d[2],d[3],d[4]])?"Bauplatz wählen":"Rohstoffe fehlen")+'</button></article>').join("")+'</div>'}
