function quests(){resetQuests();const q=[["cards","🃏","Wissenswiederholung","Wiederhole 20 Karteikarten.",s.daily.cards,20,350,30],["trainer","🎯","Prüfungstrainer","Schließe 3 Trainer-Durchgänge ab.",s.daily.trainers,3,450,35],["minutes","⏱️","Fokuszeit","Lerne heute insgesamt 30 Minuten mit dem Timer.",s.daily.minutes,30,400,30]];const week=[["weeklyCards","📚","Wöchentliche Wiederholung","Wiederhole 100 Karteikarten.",s.weekly.cards,100,900,80],["weeklyMinutes","⌛","Wöchentliche Fokuszeit","Lerne 180 Minuten mit dem Timer.",s.weekly.minutes,180,1200,100]];return '<div class="empire-heading"><div><span class="empire-kicker">LERNEN · AUFTRÄGE · BELOHNUNGEN</span><h2>Quests & Lernübersicht</h2><p>Fortschritt wird automatisch aus Timer, Karteikarten und Trainer übernommen.</p></div></div><h3>Tägliche Aufträge</h3><div class="empire-cards">'+q.map(a=>questCard(...a,s.daily.claimed)).join("")+'</div><h3>Wöchentliche Herausforderungen</h3><div class="empire-cards">'+week.map(a=>questCard(...a,s.weekly.claimed)).join("")+'</div><div class="empire-info"><h3>📈 Deine Lernbilanz</h3><p>Gesamt: '+s.allTimeMinutes+' Minuten · '+s.allTimeMinutes*50+' Coins · '+s.allTimeMinutes*5+' XP · '+s.daily.cards+' Karten heute · '+s.daily.trainers+' Trainer heute.</p><p>Nur abgeschlossene, gespeicherte Timer-Sessions werden angerechnet. Jede Session wird genau einmal verarbeitet.</p></div>'}
