 const policy=[["balanced","⚖️ Ausgewogen","Stabile Versorgung und Entwicklung."],["welfare","💚 Soziales Netz","Mehr Zufriedenheit, aber höherer Nahrungsverbrauch."],["growth","📈 Wachstum","Mehr Produktion, aber geringere Zufriedenheit."],["education","📚 Bildung","Schulen und Bibliotheken erzeugen mehr Wissen."],["security","🛡️ Sicherheit","Mehr Verteidigung und ein ruhigeres Stadtleben."]];
 return '<div class="empire-heading"><div><span class="empire-kicker">STADTENTWICKLUNG</span><h2>Deine Bevölkerung</h2><p>Eine starke Hauptstadt braucht Wohnraum, Nahrung, Bildung, Gesundheit und sichere Wege.</p></div></div><div class="empire-cards"><article class="empire-card"><div>👥</div><h3>'+pop+' / '+cap+' Einwohner</h3><p>'+housing+' freie Wohnplätze · '+unemployed+' ohne zugewiesene Arbeit</p></article><article class="empire-card"><div>😊</div><h3>'+Math.round(s.mood)+'% Zufriedenheit</h3><p>'+parks+' Parks · '+schools+' Schulen · '+clinics+' Heilstuben</p></article><article class="empire-card"><div>🧑‍🌾</div><h3>'+employed+' Arbeitsplätze</h3><p>'+jobs+' mögliche Arbeitsplätze durch deine Gebäude</p></article><article class="empire-card"><div>🛤️</div><h3>'+roads+' Straßen</h3><p>'+defence+' Verteidigungspunkte in der Hauptstadt</p></article></div><div class="empire-info"><h3>🏛️ Stadtpolitik</h3><p>Wähle, worauf sich dein Reich konzentrieren soll. Die Entscheidung beeinflusst die Produktion und das Stadtleben.</p><div class="empire-policy-grid">'+policy.map(p=>'<button class="empire-choice '+(s.cityPolicy===p[0]?"chosen":"")+'" data-action="citypolicy" data-id="'+p[0]+'"><b>'+p[1]+'</b><small>'+p[2]+'</small></button>').join("")+'</div></div><div class="empire-info"><h3>🏗️ Stadtentwicklung</h3><p>Wohnhäuser schaffen Platz. Parks, Schulen und Heilstuben verbessern die Lebensqualität. Straßen verbinden deine Gebäude und Wachposten erhöhen die Sicherheit.</p><button class="empire-btn" data-tab="build">Gebäude errichten</button> <button class="empire-btn secondary" data-tab="map">Stadt auf der Karte ansehen</button></div><div class="empire-info"><h3>📜 Letzte Ereignisse</h3><ul class="empire-event-list">'+(s.eventLog||[]).slice(-8).reverse().map(x=>'<li>'+esc(x)+'</li>').join("")+'</ul></div>';
