function council(){return '<div class="empire-heading"><div><span class="empire-kicker">STAATSRAT</span><h2>Politik & Bevölkerung</h2><p>Deine Entscheidungen beeinflussen Zufriedenheit und Arbeitsleistung.</p></div></div><div class="empire-cards"><article class="empire-card wide"><h3>Steuer- und Versorgungspolitik</h3><p>Die Steuerpolitik erzeugt keine Coins – sie beeinflusst die Zufriedenheit und die Produktivität.</p>'+[["low","Entlastung","Zufriedenheit steigt, Produktion etwas langsamer."],["normal","Ausgewogen","Stabile Zufriedenheit und normale Produktion."],["high","Sparpolitik","Mehr Produktion, aber Zufriedenheit sinkt."]].map(a=>'<button class="empire-choice '+(s.tax===a[0]?"chosen":"")+'" data-action="tax" data-id="'+a[0]+'">'+a[1]+'</button><small>'+a[2]+'</small>').join("")+'</article><article class="empire-card wide"><h3>Reichsstatistik</h3><p>Stufe '+s.level+' · '+s.buildings.length+' Gebäude · '+s.pop+' Einwohner · '+totalUnits()+' Truppen · '+Math.round(s.mood)+'% Zufriedenheit</p><p>Gelernte Zeit: '+Math.floor(s.allTimeMinutes/60)+' Std. '+s.allTimeMinutes%60+' Min.</p></article></div>'}

const worldLinks={capital:["river","iron"],river:["capital","north","coast"],iron:["capital","coast"],coast:["iron","river"],north:["river"]};
const realmDefaults={vale:{name:"Herzogtum Valen",level:2,pop:420,prosperity:62,stock:180,focus:"Landwirtschaft",buildings:7,army:34,capital:"Weidenhall"},stone:{name:"Bergbund Khador",level:3,pop:360,prosperity:54,stock:110,focus:"Handwerk",buildings:9,army:52,capital:"Granitwacht"},coast:{name:"Freie Küstenstädte",level:2,pop:510,prosperity:68,stock:145,focus:"Handel",buildings:8,army:28,capital:"Hafenbund"}};
const aiFocusOffers={vale:{give:"wheat",get:"wood",qty:48,amount:30},stone:{give:"wood",get:"stone",qty:44,amount:32},coast:{give:"bread",get:"planks",qty:28,amount:16}};
function aiOffer(id){const base=aiFocusOffers[id],a=s.aiRealms[id]||realmDefaults[id];if(!base)return null;const prosperity=Math.max(.75,Math.min(1.25,(Number(a.prosperity)||50)/65));const qty=Math.max(15,Math.round(base.qty*(a.level>=5?1.15:1)));const amount=Math.max(8,Math.round(base.amount*prosperity*(s.treaties||[]).includes(id)?1.12:1));return {give:base.give,get:base.get,qty,amount,stock:Math.max(20,Number(a.stock)||20)}}
function aiWorldTick(){
 const day=DAY();if(s.aiLastDay===day)return;s.aiLastDay=day;s.aiRealms=s.aiRealms||{};s.aiEvents=Array.isArray(s.aiEvents)?s.aiEvents:[];s.aiPacts=Array.isArray(s.aiPacts)?s.aiPacts:[];s.relations=s.relations||{vale:25,stone:15,coast:10};
 const ids=Object.keys(realmDefaults),daily=[];
 for(const [id,base] of Object.entries(realmDefaults)){
  const a=s.aiRealms[id]&&typeof s.aiRealms[id]==="object"?s.aiRealms[id]:{...base};
  a.level=Math.max(1,Number(a.level)||base.level);a.pop=Math.max(100,Number(a.pop)||base.pop);a.prosperity=Math.max(20,Math.min(100,Number(a.prosperity)||base.prosperity));a.stock=Math.max(20,Number(a.stock)||base.stock);a.buildings=Math.max(3,Number(a.buildings)||base.buildings);a.army=Math.max(10,Number(a.army)||base.army);a.focus=a.focus||base.focus;
  const seed=[...day+id].reduce((n,ch)=>(n*33+ch.charCodeAt(0))>>>0,7),decision=seed%6;
  a.pop+=8+(seed%13);a.stock+=8+(seed%17);a.prosperity=Math.max(20,Math.min(100,a.prosperity+((seed%5)-2)));
  let action="";
  if(decision===0){a.stock+=28;a.prosperity=Math.min(100,a.prosperity+2);action="hat seine Vorratsspeicher erweitert";}
  else if(decision===1){a.prosperity=Math.min(100,a.prosperity+4);a.stock=Math.max(20,a.stock-8);action="hat Handelswege ausgebaut";}
  else if(decision===2){a.stock=Math.max(20,a.stock-15);a.prosperity=Math.min(100,a.prosperity+3);action="hat ein Erntefest veranstaltet";}
  else if(decision===3){a.buildings++;a.stock=Math.max(20,a.stock-18);a.prosperity=Math.min(100,a.prosperity+2);action="hat ein neues Gebäude errichtet";}
  else if(decision===4){a.army+=3;a.stock=Math.max(20,a.stock-12);a.prosperity=Math.max(20,a.prosperity-1);action="hat seine Grenzwache verstärkt";}
  else{a.stock+=22;a.prosperity=Math.max(20,a.prosperity-2);action="hat Werkstätten erweitert";}
  if(a.prosperity>=78&&seed%3===0&&a.level<8){a.level++;a.buildings+=2;action+=" und ist auf Reichsstufe "+a.level+" aufgestiegen";}
  if(a.prosperity<32){a.pop=Math.max(100,a.pop-5);action+="; die Bevölkerung wächst langsamer";}
  a.lastAction=action;a.lastUpdate=day;s.aiRealms[id]=a;
  const rel=Number(s.relations[id])||0;s.relations[id]=Math.max(0,Math.min(100,rel+(a.prosperity>75?1:a.prosperity<30?-1:0)));
  daily.push({day,id,name:base.name,text:action});
 }
 // Nachbarreiche schließen gelegentlich untereinander Handelsabkommen; das verändert ihre Entwicklung, nicht den Spielerkontostand.
 if((Number(day.replace(/-/g,""))||0)%3===0){const pair=ids[(Number(day.replace(/-/g,""))||0)%ids.length]+"-"+ids[((Number(day.replace(/-/g,""))||0)+1)%ids.length];if(!s.aiPacts.includes(pair)){s.aiPacts.push(pair);daily.unshift({day,id:"pact",name:"Nachbarreiche",text:pair.replace("-"," und ")+" haben ein Handelsabkommen geschlossen"});}}
 s.aiPacts=s.aiPacts.slice(-8);s.aiEvents=daily.concat(s.aiEvents).slice(0,12);save();
}
